import sys
from collections import deque

def min_path_length(x1, y1, x2, y2):
    if (x1, y1) == (x2, y2):
        return 0

    visited = set()
    queue = deque([(x1, y1, 0)])
    visited.add((x1, y1))

    while queue:
        x, y, steps = queue.popleft()

        if x == x2 and y == y2:
            return steps * 2 + abs(x1 - x2) + abs(y1 - y2)

        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in visited and -100 <= nx <= 100 and -100 <= ny <= 100:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1  # No valid path found

def main():
    x1, y1 = map(int, input().split())
    x2, y2 = map(int, input().split())

    result = min_path_length(x1, y1, x2, y2)
    print(result)

if __name__ == "__main__":
    main()
